  --foreground: #1b1e2b;

  /* card and popover */
  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;

  /* muted surface, muted text, subtle hover surface */
  --secondary: #eef0f6;
