import { Component, computed, input } from '@angular/core';
import { RouterLink } from '@angular/router';
import { HlmAvatar, HlmAvatarFallback } from '@spartan-ng/helm/avatar';
import { HlmBadge } from '@spartan-ng/helm/badge';
import { HlmButton } from '@spartan-ng/helm/button';
import { HlmCardImports } from '@spartan-ng/helm/card';
import { HlmH4, HlmMuted } from '@spartan-ng/helm/typography';
import type { BadgeVariants } from '../../../../libs/ui/badge/src/lib/hlm-badge';
import type { Hero, HeroPowerClass, HeroStatus } from '../../hero/hero.model';
import { PowerMeter } from '../power-meter/power-meter';

const STATUS_VARIANT: Record<HeroStatus, BadgeVariants['variant']> = {
  Active: 'success',
  Injured: 'warning',
  Reserve: 'secondary',
  MIA: 'destructive',
};

const CLASS_VARIANT: Record<HeroPowerClass, BadgeVariants['variant']> = {
  Aerial: 'default',
  Energy: 'secondary',
  Psionic: 'destructive',
  Tech: 'secondary',
  Mutant: 'default',
  Cosmic: 'outline',
  Enhanced: 'default',
};

/** Two initials from the codename, for the portrait placeholder. */
function initialsOf(name: string): string {
  return name
    .split(/\s+/)
    .filter((part) => part.length > 0)
    .slice(0, 2)
    .map((part) => part.charAt(0).toUpperCase())
    .join('');
}

@Component({
  selector: 'app-hero-card',
  imports: [
    RouterLink,
    HlmAvatar,
    HlmAvatarFallback,
    HlmBadge,
    HlmButton,
    HlmCardImports,
    HlmH4,
    HlmMuted,
    PowerMeter,
  ],
  templateUrl: './hero-card.html',
  styleUrl: './hero-card.css',
})
export class HeroCard {
  public readonly hero = input.required<Hero>();

  protected readonly initials = computed(() => initialsOf(this.hero().name));
  protected readonly statusVariant = computed(() => STATUS_VARIANT[this.hero().status]);
  protected readonly classVariant = computed(() => CLASS_VARIANT[this.hero().powerClass]);
}

